    /// Also returns the MessageStatus of the sequence based on the incoming sequence number.
    fn handle_sequence_num(&mut self, seq_num: SequenceNumber, from: NodeId) -> MessageStatus {
        let msg_status = self.current_seq_num.check_msg_status(seq_num);
        match msg_status {
            MessageStatus::Expected => self.current_seq_num = seq_num,
            MessageStatus::DroppedPreceding => self.reconnected(from),
            MessageStatus::Outdated => (),
        };
        msg_status
    }

    pub(crate) fn resend_messages_follower(&mut self) {
        match self.state.1 {
            Phase::Prepare => {
                // Resend Promise
                match &self.cached_promise_message {
                    Some(promise) => {
                        self.outgoing.push(Message::SequencePaxos(PaxosMessage {
                            from: self.pid,
                            to: promise.n.pid,
                            msg: PaxosMsg::Promise(promise.clone()),
                        }));
                    }
                    None => {
                        // Shouldn't be possible to be in prepare phase without having
                        // cached the promise sent as a response to the prepare
                        #[cfg(feature = "logging")]
                        warn!(self.logger, "In Prepare phase without a cached promise!");
                        self.state = (Role::Follower, Phase::Recover);
                        self.send_preparereq_to_all_peers();
                    }
                }
            }
            Phase::Recover => {
                // Resend PrepareReq
                self.send_preparereq_to_all_peers();
            }
            Phase::Accept => (),
            Phase::None => (),
        }
    }

    fn send_preparereq_to_all_peers(&mut self) {
        let prepreq = PrepareReq {
            n: self.get_promise(),
        };
        for peer in &self.peers {
            self.outgoing.push(Message::SequencePaxos(PaxosMessage {
                from: self.pid,
                to: *peer,
                msg: PaxosMsg::PrepareReq(prepreq),
            }));
        }
    }

    pub(crate) fn flush_batch_follower(&mut self) {
        let accepted_idx = self.internal_storage.get_accepted_idx();
        let new_accepted_idx = self.internal_storage.flush_batch().expect(WRITE_ERROR_MSG);
        if new_accepted_idx > accepted_idx {
            self.reply_accepted(self.get_promise(), new_accepted_idx);
        }
    }
}

pub(crate) fn resend_message_timeout(&mut self) {
    match self.state.0 {
        Role::Leader => self.resend_messages_leader(),
        Role::Follower => self.resend_messages_follower(),
    }
}

/// Flushes any batched log entries and sends their corresponding Accept or Accepted messages.
pub(crate) fn flush_batch_timeout(&mut self) {
    match self.state {
        (Role::Leader, Phase::Accept) => self.flush_batch_leader(),
        (Role::Follower, Phase::Accept) => self.flush_batch_follower(),
        _ => (),
    }
}

/// Moves the outgoing messages from this replica into the buffer. The messages should then be sent via the network implementation.
/// If `buffer` is empty, it gets swapped with the internal message buffer. Otherwise, messages are appended to the buffer. This prevents messages from getting discarded.
/// the buffer.
pub(crate) fn take_outgoing_msgs(&mut self, buffer: &mut Vec<Message<T>>) {
    if buffer.is_empty() {
        std::mem::swap(buffer, &mut self.outgoing);
    } else {
        // User has unsent messages in their buffer, must extend their buffer.
        buffer.append(&mut self.outgoing);
    }
    self.leader_state.reset_latest_accept_meta();
    self.latest_accepted_meta = None;
}

/// Handle an incoming message.
pub(crate) fn handle(&mut self, m: PaxosMessage<T>) {
    match m.msg {
        PaxosMsg::PrepareReq(prepreq) => self.handle_preparereq(prepreq, m.from),
        PaxosMsg::Prepare(prep) => self.handle_prepare(prep, m.from),
        PaxosMsg::Promise(prom) => match &self.state {
            (Role::Leader, Phase::Prepare) => self.handle_promise_prepare(prom, m.from),
            (Role::Leader, Phase::Accept) => self.handle_promise_accept(prom, m.from),
            _ => {}
        },
        PaxosMsg::AcceptSync(acc_sync) => self.handle_acceptsync(acc_sync, m.from),
        PaxosMsg::AcceptDecide(acc) => self.handle_acceptdecide(acc),
        PaxosMsg::NotAccepted(not_acc) => self.handle_notaccepted(not_acc, m.from),
        PaxosMsg::Accepted(accepted) => self.handle_accepted(accepted, m.from),
        PaxosMsg::Decide(d) => self.handle_decide(d),
        PaxosMsg::ProposalForward(proposals) => self.handle_forwarded_proposal(proposals),
        PaxosMsg::Compaction(c) => self.handle_compaction(c),
        PaxosMsg::AcceptStopSign(acc_ss) => self.handle_accept_stopsign(acc_ss),
        PaxosMsg::ForwardStopSign(f_ss) => self.handle_forwarded_stopsign(f_ss),
    }
}

/// Returns whether this Sequence Paxos has been reconfigured
pub(crate) fn is_reconfigured(&self) -> Option<StopSign> {
    match self.internal_storage.get_stopsign() {
        Some(ss) if self.internal_storage.stopsign_is_decided() => Some(ss),
        _ => None,
    }
}

/// Returns whether this Sequence Paxos instance is stopped, i.e. if it has been reconfigured.
fn accepted_reconfiguration(&self) -> bool {
    self.internal_storage.get_stopsign().is_some()
}

/// Append an entry to the replicated log.
pub(crate) fn append(&mut self, entry: T) -> Result<(), ProposeErr<T>> {
    if self.accepted_reconfiguration() {
        Err(ProposeErr::PendingReconfigEntry(entry))
    } else {
        self.propose_entry(entry);
        Ok(())
    }
}

/// Propose a reconfiguration. Returns an error if already stopped or `new_config` is invalid.
/// `new_config` defines the cluster-wide configuration settings for the next cluster.
/// `metadata` is optional data to commit alongside the reconfiguration.
pub(crate) fn reconfigure(
    &mut self,
    new_config: ClusterConfig,
    metadata: Option<Vec<u8>>,
) -> Result<(), ProposeErr<T>> {
    if self.accepted_reconfiguration() {
        return Err(ProposeErr::PendingReconfigConfig(new_config, metadata));
    }
    #[cfg(feature = "logging")]
    info!(
        self.logger,
        "Accepting reconfiguration {:?}", new_config.nodes
    );
    let ss = StopSign::with(new_config, metadata);
    match self.state {
        (Role::Leader, Phase::Prepare) => self.buffered_stopsign = Some(ss),
        (Role::Leader, Phase::Accept) => self.accept_stopsign_leader(ss),

}

/// Handles re-establishing a connection to a previously disconnected peer.
/// This should only be called if the underlying network implementation indicates that a connection has been re-established.
pub(crate) fn reconnected(&mut self, pid: NodeId) {
    if pid == self.pid {
        return;
    } else if pid == self.get_current_leader() {
        self.state = (Role::Follower, Phase::Recover);
    }
    let prepreq = PrepareReq {
        n: self.get_promise(),
    };
    self.outgoing.push(Message::SequencePaxos(PaxosMessage {
        from: self.pid,
        to: pid,
        msg: PaxosMsg::PrepareReq(prepreq),
    }));
}

fn propose_entry(&mut self, entry: T) {
    match self.state {
        (Role::Leader, Phase::Prepare) => self.buffered_proposals.push(entry),
        (Role::Leader, Phase::Accept) => self.accept_entry_leader(entry),
        _ => self.forward_proposals(vec![entry]),
    }
}

pub(crate) fn get_leader_state(&self) -> &LeaderState<T> {
    &self.leader_state
}

pub(crate) fn forward_proposals(&mut self, mut entries: Vec<T>) {
    let leader = self.get_current_leader();
    if leader > 0 && self.pid != leader {
        let pf = PaxosMsg::ProposalForward(entries);
        let msg = Message::SequencePaxos(PaxosMessage {
            from: self.pid,
            to: leader,
            msg: pf,
        });
        self.outgoing.push(msg);
    } else {
        self.buffered_proposals.append(&mut entries);
    }
}

pub(crate) fn forward_stopsign(&mut self, ss: StopSign) {
    let leader = self.get_current_leader();
    if leader > 0 && self.pid != leader {
        #[cfg(feature = "logging")]
        trace!(self.logger, "Forwarding StopSign to Leader {:?}", leader);
        let fs = PaxosMsg::ForwardStopSign(ss);
        let msg = Message::SequencePaxos(PaxosMessage {
            from: self.pid,
            to: leader,
            msg: fs,
        });
        self.outgoing.push(msg);
    } else if self.buffered_stopsign.as_mut().is_none() {
        self.buffered_stopsign = Some(ss);
    }
}
/// Returns `LogSync`, a struct to help other servers synchronize their log to correspond to the
/// current state of our own log. The `common_prefix_idx` marks where in the log the other server
/// needs to be sync from.
fn create_log_sync(
    &self,
    common_prefix_idx: usize,
    other_logs_decided_idx: usize,
) -> LogSync<T> {
    let decided_idx = self.internal_storage.get_decided_idx();
    let (decided_snapshot, suffix, sync_idx) =
        if T::Snapshot::use_snapshots() && decided_idx > common_prefix_idx {
            // Note: We snapshot from the other log's decided index and not the common prefix because
            // snapshots currently only work on decided entries.
            let (delta_snapshot, compacted_idx) = self
                .internal_storage
                .create_diff_snapshot(other_logs_decided_idx)
                .expect(READ_ERROR_MSG);
            let suffix = self
                .internal_storage
                .get_suffix(decided_idx)
                .expect(READ_ERROR_MSG);
            (delta_snapshot, suffix, compacted_idx)
        } else {
            let suffix = self
                .internal_storage
                .get_suffix(common_prefix_idx)
                .expect(READ_ERROR_MSG);
            (None, suffix, common_prefix_idx)
        };
    LogSync {
        decided_snapshot,
        suffix,
        sync_idx,
        stopsign: self.internal_storage.get_stopsign(),
    }
}

/// Creates a Sequence Paxos replica.
pub(crate) fn with(config: SequencePaxosConfig, storage: B) -> Self {
    let pid = config.pid;
    let peers = config.peers;
    let num_nodes = &peers.len() + 1;
    let quorum = Quorum::with(config.flexible_quorum, num_nodes);
    let max_peer_pid = peers.iter().max().unwrap();
    let max_pid = *std::cmp::max(max_peer_pid, &pid) as usize;
    let mut outgoing = Vec::with_capacity(config.buffer_size);
    let (state, leader) = match storage
        .get_promise()
        .expect("storage error while trying to read promise")
    {
        // if we recover a promise from storage then we must do failure recovery
        Some(b) => {
            let state = (Role::Follower, Phase::Recover);
            for peer_pid in &peers {
                let prepreq = PrepareReq { n: b };
                outgoing.push(Message::SequencePaxos(PaxosMessage {
                    from: pid,
                    to: *peer_pid,
                    msg: PaxosMsg::PrepareReq(prepreq),
                }));
            }
            (state, b)
        }
        None => ((Role::Follower, Phase::None), Ballot::default()),
    };
    let internal_storage_config = InternalStorageConfig {
        batch_size: config.batch_size,
    };
    let mut paxos = SequencePaxos {
        internal_storage: InternalStorage::with(
            storage,
            internal_storage_config,
            #[cfg(feature = "unicache")]
            pid,
        ),
        pid,
        peers,
        state,
        buffered_proposals: vec![],
        buffered_stopsign: None,
        outgoing,
        leader_state: LeaderState::<T>::with(leader, max_pid, quorum),
        latest_accepted_meta: None,
        current_seq_num: SequenceNumber::default(),
        cached_promise_message: None,
        #[cfg(feature = "logging")]
        logger: {
            if let Some(logger) = config.custom_logger {
                logger
            } else {
                let s = config
                    .logger_file_path
                    .unwrap_or_else(|| format!("logs/paxos_{}.log", pid));
                create_logger(s.as_str())
            }
        },
    };
    paxos
        .internal_storage
        .set_promise(leader)
        .expect(WRITE_ERROR_MSG);
    #[cfg(feature = "logging")]
    {
        info!(paxos.logger, "Paxos component pid: {} created!", pid);
        if let Quorum::Flexible(flex_quorum) = quorum {
            if flex_quorum.read_quorum_size > num_nodes - flex_quorum.write_quorum_size + 1 {
                warn!(
                    paxos.logger,
                    "Unnecessary overlaps in read and write quorums. Read and Write quorums only need to be overlapping by one node i.e., read_quorum_size + write_quorum_size = num_nodes + 1");

    T: Entry,
{
    pub fn with(n_leader: Ballot, max_pid: usize, quorum: Quorum) -> Self {
        Self {
            n_leader,
            promises_meta: vec![PromiseState::NotPromised; max_pid],
            follower_seq_nums: vec![SequenceNumber::default(); max_pid],
            accepted_indexes: vec![0; max_pid],
            max_promise_meta: PromiseMetaData::default(),
            max_promise_sync: None,
            latest_accept_meta: vec![None; max_pid],
            max_pid,
            quorum,
        }
    }

    fn pid_to_idx(pid: NodeId) -> usize {
        (pid - 1) as usize
    }

    // Resets `pid`'s accept sequence to indicate they are in the next session of accepts
    pub fn increment_seq_num_session(&mut self, pid: NodeId) {
        let idx = Self::pid_to_idx(pid);
        self.follower_seq_nums[idx].session += 1;
        self.follower_seq_nums[idx].counter = 0;
    }

    pub fn next_seq_num(&mut self, pid: NodeId) -> SequenceNumber {
        let idx = Self::pid_to_idx(pid);
        self.follower_seq_nums[idx].counter += 1;
        self.follower_seq_nums[idx]
    }

    pub fn get_seq_num(&mut self, pid: NodeId) -> SequenceNumber {
        self.follower_seq_nums[Self::pid_to_idx(pid)]
    }

    pub fn set_promise(&mut self, prom: Promise<T>, from: NodeId, check_max_prom: bool) -> bool {
        let promise_meta = PromiseMetaData {
            n_accepted: prom.n_accepted,
            accepted_idx: prom.accepted_idx,
            decided_idx: prom.decided_idx,
            pid: from,
        };
        if check_max_prom && promise_meta > self.max_promise_meta {
            self.max_promise_meta = promise_meta.clone();
            self.max_promise_sync = prom.log_sync;
        }
        self.promises_meta[Self::pid_to_idx(from)] = PromiseState::Promised(promise_meta);
        let num_promised = self
            .promises_meta
            .iter()
            .filter(|p| matches!(p, PromiseState::Promised(_)))
            .count();
        self.quorum.is_prepare_quorum(num_promised)
    }

    pub fn reset_promise(&mut self, pid: NodeId) {
        self.promises_meta[Self::pid_to_idx(pid)] = PromiseState::NotPromised;
    }

    /// Node `pid` seen with ballot greater than my ballot
    pub fn lost_promise(&mut self, pid: NodeId) {
        self.promises_meta[Self::pid_to_idx(pid)] = PromiseState::PromisedHigher;
    }

    pub fn take_max_promise_sync(&mut self) -> Option<LogSync<T>> {
        std::mem::take(&mut self.max_promise_sync)
    }

    pub fn get_max_promise_meta(&self) -> &PromiseMetaData {
        &self.max_promise_meta
    }

    pub fn get_max_decided_idx(&self) -> usize {
        self.promises_meta
            .iter()
            .filter_map(|p| match p {
                PromiseState::Promised(m) => Some(m.decided_idx),
                _ => None,
            })
            .max()
            .unwrap_or_default()
    }

    pub fn get_promise_meta(&self, pid: NodeId) -> &PromiseMetaData {
        match &self.promises_meta[Self::pid_to_idx(pid)] {
            PromiseState::Promised(metadata) => metadata,
            _ => panic!("No Metadata found for promised follower"),
        }
    }

    pub fn get_min_all_accepted_idx(&self) -> &usize {
        self.accepted_indexes
            .iter()
            .min()
            .expect("Should be all initialised to 0!")
    }

    pub fn reset_latest_accept_meta(&mut self) {
        self.latest_accept_meta = vec![None; self.max_pid];
    }

    pub fn get_promised_followers(&self) -> Vec<NodeId> {
        self.promises_meta
            .iter()
            .enumerate()
            .filter_map(|(idx, x)| match x {
                PromiseState::Promised(_) if idx != Self::pid_to_idx(self.n_leader.pid) => {
                    Some((idx + 1) as NodeId)
                }
                _ => None,
            })
            .collect()
    }

    /// The pids of peers which have not promised a higher ballot than mine.
    pub(crate) fn get_preparable_peers(&self, peers: &[NodeId]) -> Vec<NodeId> {
        peers
            .iter()
            .filter_map(|pid| {
                let idx = Self::pid_to_idx(*pid);
                match self.promises_meta.get(idx).unwrap() {
                    PromiseState::NotPromised => Some(*pid),
                    _ => None,
                }
            })
            .collect()
    }

    pub fn set_latest_accept_meta(&mut self, pid: NodeId, idx: Option<usize>) {
        let meta = idx.map(|x| (self.n_leader, x));
        self.latest_accept_meta[Self::pid_to_idx(pid)] = meta;
    }

    pub fn set_accepted_idx(&mut self, pid: NodeId, idx: usize) {
        self.accepted_indexes[Self::pid_to_idx(pid)] = idx;
    }

    pub fn get_latest_accept_meta(&self, pid: NodeId) -> Option<(Ballot, usize)> {
        self.latest_accept_meta
            .get(Self::pid_to_idx(pid))
            .unwrap()
            .as_ref()
            .copied()
    }

    pub fn get_decided_idx(&self, pid: NodeId) -> Option<usize> {
        match self.promises_meta.get(Self::pid_to_idx(pid)).unwrap() {
            PromiseState::Promised(metadata) => Some(metadata.decided_idx),
            _ => None,
        }
    }

    pub fn get_accepted_idx(&self, pid: NodeId) -> usize {
        *self.accepted_indexes.get(Self::pid_to_idx(pid)).unwrap()
    }

    pub fn is_chosen(&self, idx: usize) -> bool {
        let num_accepted = self
            .accepted_indexes
            .iter()
            .filter(|la| **la >= idx)
            .count();
        self.quorum.is_accept_quorum(num_accepted)
    }
}

/// The entry read in the log.
#[derive(Debug, Clone)]
pub enum LogEntry<T>
where
    T: Entry,
{
    /// The entry is decided.
    Decided(T),
    /// The entry is NOT decided. Might be removed from the log at a later time.
    Undecided(T),
    /// The entry has been trimmed.
    Trimmed(TrimmedIndex),
    /// The entry has been snapshotted.
    Snapshotted(SnapshottedEntry<T>),
    /// This Sequence Paxos instance has been stopped for reconfiguration. The accompanying bool
    /// indicates whether the reconfiguration has been decided or not. If it is `true`, then the OmniPaxos instance for the new configuration can be started.
    StopSign(StopSign, bool),
}

impl<T: PartialEq + Entry> PartialEq for LogEntry<T>
where
    <T as Entry>::Snapshot: PartialEq,
{
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (LogEntry::Decided(v1), LogEntry::Decided(v2)) => v1 == v2,
            (LogEntry::Undecided(v1), LogEntry::Undecided(v2)) => v1 == v2,

/// Flexible quorums can be used to increase/decrease the read and write quorum sizes,
/// for different latency vs fault tolerance tradeoffs.
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
#[cfg_attr(any(feature = "serde", feature = "toml_config"), derive(Deserialize))]
#[cfg_attr(feature = "serde", derive(Serialize))]
pub struct FlexibleQuorum {
    /// The number of nodes a leader needs to consult to get an up-to-date view of the log.
    pub read_quorum_size: usize,
    /// The number of acknowledgments a leader needs to commit an entry to the log
    pub write_quorum_size: usize,
}

/// The type of quorum used by the OmniPaxos cluster.
#[derive(Copy, Clone, Debug)]
pub(crate) enum Quorum {
    /// Both the read quorum and the write quorums are a majority of nodes
    Majority(usize),
    /// The read and write quorum sizes are defined by a `FlexibleQuorum`
    Flexible(FlexibleQuorum),
}

impl Quorum {
    pub(crate) fn with(flexible_quorum_config: Option<FlexibleQuorum>, num_nodes: usize) -> Self {
        match flexible_quorum_config {
            Some(FlexibleQuorum {
                read_quorum_size,
                write_quorum_size,
            }) => Quorum::Flexible(FlexibleQuorum {
                read_quorum_size,
                write_quorum_size,
            }),
            None => Quorum::Majority(num_nodes / 2 + 1),
        }
    }

    pub(crate) fn is_prepare_quorum(&self, num_nodes: usize) -> bool {
        match self {
            Quorum::Majority(majority) => num_nodes >= *majority,
            Quorum::Flexible(flex_quorum) => num_nodes >= flex_quorum.read_quorum_size,
        }
    }

    pub(crate) fn is_accept_quorum(&self, num_nodes: usize) -> bool {
        match self {
            Quorum::Majority(majority) => num_nodes >= *majority,
            Quorum::Flexible(flex_quorum) => num_nodes >= flex_quorum.write_quorum_size,
        }
    }
}

/// The entries flushed due to an append operation
pub(crate) struct AcceptedMetaData<T: Entry> {
    pub accepted_idx: usize,

    }

    /// End of a heartbeat round. Returns current leader and election status.
    pub(crate) fn hb_timeout(
        &mut self,
        seq_paxos_state: &(Role, Phase),
        seq_paxos_promise: Ballot,
    ) -> Option<Ballot> {
        self.update_leader();
        self.update_happiness(seq_paxos_state);
        self.check_takeover();
        self.new_hb_round();
        if seq_paxos_promise > self.leader {
            // Sync leader with Paxos promise in case ballot didn't make it to BLE followers
            // or become_leader() was called.
            self.leader = seq_paxos_promise;
            if seq_paxos_promise.pid == self.pid {
                self.current_ballot = seq_paxos_promise;
            }
            self.happy = true;
        }
        if self.leader == self.current_ballot {
            Some(self.current_ballot)
        } else {
            None
        }
    }

    fn update_leader(&mut self) {
        let max_reply_ballot = self.heartbeat_replies.iter().map(|r| r.ballot).max();
        if let Some(max) = max_reply_ballot {
            if max > self.leader {
                self.leader = max;
            }
        }
    }

    fn update_happiness(&mut self, seq_paxos_state: &(Role, Phase)) {
        self.happy = if self.leader == self.current_ballot {
            let potential_followers = self
                .heartbeat_replies
                .iter()
                .filter(|hb_reply| hb_reply.leader <= self.current_ballot)
                .count();
            let can_form_quorum = match seq_paxos_state {
                (Role::Leader, Phase::Accept) => {
                    self.quorum.is_accept_quorum(potential_followers + 1)
                }
                _ => self.quorum.is_prepare_quorum(potential_followers + 1),
            };
            if can_form_quorum {
                true
            } else {
                let see_larger_happy_leader = self
                    .heartbeat_replies
                    .iter()
                    .any(|r| r.leader > self.current_ballot && r.happy);
                see_larger_happy_leader
            }
        } else {
            self.heartbeat_replies
                .iter()
                .any(|r| r.ballot == self.leader && r.happy)
        };
    }

    fn check_takeover(&mut self) {
        if !self.happy {
            let all_neighbors_unhappy = self.heartbeat_replies.iter().all(|r| !r.happy);
            let im_quorum_connected = self
                .quorum
                .is_prepare_quorum(self.heartbeat_replies.len() + 1);
            if all_neighbors_unhappy && im_quorum_connected {
                // We increment past our leader instead of max of unhappy ballots because we
                // assume we have already checked leader for this round so they should be equal
                self.current_ballot.n = self.leader.n + 1;
                self.leader = self.current_ballot;
                self.happy = true;
            }
        }
    }

    fn handle_request(&mut self, from: NodeId, req: HeartbeatRequest) {
        let hb_reply = HeartbeatReply {
            round: req.round,
            ballot: self.current_ballot,
            leader: self.leader,
            happy: self.happy,
        };
        self.outgoing.push(BLEMessage {
            from: self.pid,
            to: from,
            msg: HeartbeatMsg::Reply(hb_reply),
        });
    }

    fn handle_reply(&mut self, rep: HeartbeatReply) {
        if rep.round == self.hb_round && rep.ballot.config_id == self.configuration_id {
            self.heartbeat_replies.push(rep);
        }
    }

    pub(crate) fn get_current_ballot(&self) -> Ballot {
        self.current_ballot
    }

    pub(crate) fn get_ballots(&self) -> Vec<HeartbeatReply> {
        self.prev_replies.clone()
    }
}

/// Configuration for `BallotLeaderElection`.
/// # Fields
/// * `configuration_id`: The identifier for the configuration that this node is part of.
/// * `pid`: The unique identifier of this node. Must not be 0.
/// * `peers`: The peers of this node i.e. the `pid`s of the other servers in the configuration.
/// * `priority`: Set custom priority for this node to be elected as the leader.
/// * `flexible_quorum` : Defines read and write quorum sizes. Can be used for different latency vs fault tolerance tradeoffs.
/// * `buffer_size`: The buffer size for outgoing messages.
/// * `logger_file_path`: The path where the default logger logs events.
#[derive(Clone, Debug)]
pub(crate) struct BLEConfig {
    configuration_id: ConfigurationId,
    pid: NodeId,
    peers: Vec<NodeId>,
    priority: u32,
    flexible_quorum: Option<FlexibleQuorum>,

        .expect("storage error while trying to read log entries")
}

/// Read all decided entries starting at `from_idx` (inclusive) in the log. Returns `None` if `from_idx` is out of bounds.
pub fn read_decided_suffix(&self, from_idx: usize) -> Option<Vec<LogEntry<T>>> {
    self.seq_paxos
        .internal_storage
        .read_decided_suffix(from_idx)
        .expect("storage error while trying to read decided log suffix")
}

/// Handle an incoming message
pub fn handle_incoming(&mut self, m: Message<T>) {
    match m {
        Message::SequencePaxos(p) => self.seq_paxos.handle(p),
        Message::BLE(b) => self.ble.handle(b),
        #[cfg(feature = "async_runtime")]
        Message::AsyncRuntime(_) => {
            // Runtime-layer messages are consumed by the actor before reaching here.
            // If one leaks through (e.g. user hand-delivered), silently ignore.
        }
    }
}

/// Returns whether this Sequence Paxos has been reconfigured
pub fn is_reconfigured(&self) -> Option<StopSign> {
    self.seq_paxos.is_reconfigured()
}

/// Append an entry to the replicated log.
pub fn append(&mut self, entry: T) -> Result<(), ProposeErr<T>> {
    self.seq_paxos.append(entry)
}

/// Propose a cluster reconfiguration. Returns an error if the current configuration has already been stopped
/// by a previous reconfiguration request or if the `new_configuration` is invalid.
/// `new_configuration` defines the cluster-wide configuration settings for the **next** cluster.
/// `metadata` is optional data to commit alongside the reconfiguration.
pub fn reconfigure(
    &mut self,
    new_configuration: ClusterConfig,
    metadata: Option<Vec<u8>>,
) -> Result<(), ProposeErr<T>> {
    if let Err(config_error) = new_configuration.validate() {
        return Err(ProposeErr::ConfigError(
            config_error,
            new_configuration,
            metadata,
        ));
    }
    self.seq_paxos.reconfigure(new_configuration, metadata)
}

/// Handles re-establishing a connection to a previously disconnected peer.
/// This should only be called if the underlying network implementation indicates that a connection has been re-established.
pub fn reconnected(&mut self, pid: NodeId) {
    self.seq_paxos.reconnected(pid)
}

/// Increments the internal logical clock. This drives the processes for leader changes, resending dropped messages, and flushing batched log entries.
/// Each of these is triggered every `election_tick_timeout`, `resend_message_tick_timeout`, and `flush_batch_tick_timeout` number of calls to this function
/// (See how to configure these timeouts in `ServerConfig`).
pub fn tick(&mut self) {
    if self.election_clock.tick_and_check_timeout() {
        self.election_timeout();
    }
    if self.resend_message_clock.tick_and_check_timeout() {
        self.seq_paxos.resend_message_timeout();
    }
    if self.flush_batch_clock.tick_and_check_timeout() {
        self.seq_paxos.flush_batch_timeout();
    }
}

/// Manually attempt to become the leader by incrementing this instance's Ballot. Calling this
/// function may not result in gainig leadership if other instances are competing for
/// leadership with higher Ballots.
pub fn try_become_leader(&mut self) {
    let mut my_ballot = self.ble.get_current_ballot();
    let promise = self.seq_paxos.get_promise();
    my_ballot.n = promise.n + 1;
    self.seq_paxos.handle_leader(my_ballot);
}

/*** BLE calls ***/
/// Update the custom priority used in the Ballot for this server. Note that changing the
/// priority triggers a leader re-election.
pub fn set_priority(&mut self, p: u32) {
    self.ble.set_priority(p)
}

/// If the heartbeat of a leader is not received when election_timeout() is called, the server might attempt to become the leader.
/// It is also used for the election process, where the server checks if it can become the leader.
/// For instance if `election_timeout()` is called every 100ms, then if the leader fails, the servers will detect it after 100ms and elect a new server after another 100ms if possible.
fn election_timeout(&mut self) {
    if let Some(new_leader) = self
        .ble
        .hb_timeout(self.seq_paxos.get_state(), self.seq_paxos.get_promise())
    {
        self.seq_paxos.handle_leader(new_leader);
    }
}

/// Returns the current states of the OmniPaxos instance for OmniPaxos UI to display.
pub fn get_ui_states(&self) -> ui::OmniPaxosStates {
    let mut cluster_state = ClusterState::from(self.seq_paxos.get_leader_state());
    cluster_state.heartbeats = self.ble.get_ballots();

    ui::OmniPaxosStates {
        current_ballot: self.ble.get_current_ballot(),
        current_leader: self.get_current_leader().map(|(leader, _)| leader),
        decided_idx: self.get_decided_idx(),
        heartbeats: self.ble.get_ballots(),
        cluster_state,
    }
}

impl OmniPaxosConfig {
    /// Checks that all the fields of the cluster config are valid.
    pub fn validate(&self) -> Result<(), ConfigError> {
        self.cluster_config.validate()?;
        self.server_config.validate()?;
        valid_config!(
            self.cluster_config.nodes.contains(&self.server_config.pid),
            "Nodes must include own server pid"
        );
        Ok(())
    }

    /// Creates a new `OmniPaxosConfig` from a `toml` file.
    #[cfg(feature = "toml_config")]
    pub fn with_toml(file_path: &str) -> Result<Self, ConfigError> {
        let config_file = fs::read_to_string(file_path)?;
        let config: OmniPaxosConfig = toml::from_str(&config_file)?;
        config.validate()?;
        Ok(config)
    }

    /// Checks all configuration fields and returns the local OmniPaxos node if successful.
    pub fn build<T, B>(self, storage: B) -> Result<OmniPaxos<T, B>, ConfigError>
    where
        T: Entry,
        B: Storage<T>,
    {
        self.validate()?;
        // Use stored ballot as initial BLE leader
        let recovered_leader = storage
            .get_promise()
            .expect("storage error while trying to read promise");
        Ok(OmniPaxos {
            ble: BallotLeaderElection::with(self.clone().into(), recovered_leader),
            election_clock: LogicalClock::with(self.server_config.election_tick_timeout),
            resend_message_clock: LogicalClock::with(
                self.server_config.resend_message_tick_timeout,
            ),
            flush_batch_clock: LogicalClock::with(self.server_config.flush_batch_tick_timeout),
            seq_paxos: SequencePaxos::with(self.into(), storage),
        })
    }
}

/// Configuration for an `OmniPaxos` cluster.
/// # Fields
/// * `configuration_id`: The identifier for the cluster configuration that this OmniPaxos server is part of.
/// * `nodes`: The nodes in the cluster i.e. the `pid`s of the other servers in the configuration.
/// * `flexible_quorum` : Defines read and write quorum sizes. Can be used for different latency vs fault tolerance tradeoffs.
#[derive(Clone, Debug, PartialEq, Default)]
#[cfg_attr(any(feature = "serde", feature = "toml_config"), derive(Deserialize))]
#[cfg_attr(feature = "toml_config", serde(default))]
#[cfg_attr(feature = "serde", derive(Serialize))]
pub struct ClusterConfig {
    /// The identifier for the cluster configuration that this OmniPaxos server is part of. Must
    /// not be 0 and be greater than the previous configuration's id.
    pub configuration_id: ConfigurationId,
    /// The nodes in the cluster i.e. the `pid`s of the servers in the configuration.
    pub nodes: Vec<NodeId>,
    /// Defines read and write quorum sizes. Can be used for different latency vs fault tolerance tradeoffs.
    pub flexible_quorum: Option<FlexibleQuorum>,
}

impl ClusterConfig {
    /// Checks that all the fields of the cluster config are valid.
    pub fn validate(&self) -> Result<(), ConfigError> {
        let num_nodes = self.nodes.len();
        valid_config!(num_nodes > 1, "Need more than 1 node");
        valid_config!(self.configuration_id != 0, "Configuration ID cannot be 0");
        if let Some(FlexibleQuorum {
            read_quorum_size,
            write_quorum_size,
        }) = self.flexible_quorum
        {
            valid_config!(
                read_quorum_size + write_quorum_size > num_nodes,
                "The quorums must overlap i.e., the sum of their sizes must exceed the # of nodes"
            );
            valid_config!(
                read_quorum_size >= 2 && read_quorum_size <= num_nodes,
                "Read quorum must be in range 2 to # of nodes in the cluster"
            );
            valid_config!(
                write_quorum_size >= 2 && write_quorum_size <= num_nodes,
                "Write quorum must be in range 2 to # of nodes in the cluster"
            );
            valid_config!(
                read_quorum_size >= write_quorum_size,
                "Read quorum size must be >= the write quorum size."
            );
        }
        Ok(())
    }

    /// Checks all configuration fields and builds a local OmniPaxos node with settings for this
    /// node defined in `server_config` and using storage `with_storage`.
    pub fn build_for_server<T, B>(
        self,
        server_config: ServerConfig,
        with_storage: B,
    ) -> Result<OmniPaxos<T, B>, ConfigError>

pub(crate) fn sync_log(
    &mut self,
    accepted_round: Ballot,
    decided_idx: usize,
    log_sync: Option<LogSync<T>>,
) -> StorageResult<usize> {
    self.state_cache.accepted_round = accepted_round;
    self.state_cache.decided_idx = decided_idx;
    let mut sync_txn: Vec<StorageOp<T>> = vec![
        StorageOp::SetAcceptedRound(accepted_round),
        StorageOp::SetDecidedIndex(decided_idx),
    ];
    if let Some(sync) = log_sync {
        match sync.decided_snapshot {
            Some(SnapshotType::Complete(c)) => {
                self.state_cache.compacted_idx = sync.sync_idx;
                sync_txn.push(StorageOp::Trim(sync.sync_idx));
                sync_txn.push(StorageOp::SetCompactedIdx(sync.sync_idx));
                sync_txn.push(StorageOp::SetSnapshot(Some(c)));
            }
            Some(SnapshotType::Delta(d)) => {
                let mut snapshot = self.create_decided_snapshot()?;
                snapshot.merge(d);
                self.state_cache.compacted_idx = sync.sync_idx;
                sync_txn.push(StorageOp::Trim(sync.sync_idx));
                sync_txn.push(StorageOp::SetCompactedIdx(sync.sync_idx));
                sync_txn.push(StorageOp::SetSnapshot(Some(snapshot)));
            }
            None => (),
        }
        self.state_cache.accepted_idx = sync.sync_idx + sync.suffix.len();
        sync_txn.push(StorageOp::AppendOnPrefix(sync.sync_idx, sync.suffix));
        match sync.stopsign {
            Some(ss) => {
                self.state_cache.stopsign = Some(ss.clone());
                self.state_cache.accepted_idx += 1;
                sync_txn.push(StorageOp::SetStopsign(Some(ss)));
            }
            None if self.state_cache.stopsign.is_some() => {
                self.state_cache.stopsign = None;
                sync_txn.push(StorageOp::SetStopsign(None));
            }
            None => (),
        }
    }
    self.storage.write_atomically(sync_txn)?;
    Ok(self.state_cache.accepted_idx)
}

fn create_decided_snapshot(&mut self) -> StorageResult<T::Snapshot> {
    let log_decided_idx = self.get_decided_idx_without_stopsign();
    self.create_snapshot(log_decided_idx)
}

pub(crate) fn create_snapshot(&self, compact_idx: usize) -> StorageResult<T::Snapshot> {
    let current_compacted_idx = self.get_compacted_idx();
    if compact_idx < current_compacted_idx {
        Err(CompactionErr::TrimmedIndex(current_compacted_idx))?
    }
    let entries = self
        .storage
        .get_entries(current_compacted_idx, compact_idx)?;
    let delta = T::Snapshot::create(entries.as_slice());
    match self.storage.get_snapshot()? {
        Some(mut s) => {
            s.merge(delta);
            Ok(s)
        }
        None => Ok(delta),
    }
}

// Creates a Delta snapshot of entries from `from_idx` to the end of the decided log and also
// returns the compacted idx of the created snapshot. If the range of entries contains entries
// which have already been compacted a valid delta cannot be created, so creates a Complete
// snapshot of the entire decided log instead.
pub(crate) fn create_diff_snapshot(
    &self,
    from_idx: usize,
) -> StorageResult<(Option<SnapshotType<T>>, usize)> {
    let log_decided_idx = self.get_decided_idx_without_stopsign();
    let compacted_idx = self.get_compacted_idx();
    let snapshot = if from_idx <= compacted_idx {
        // Some entries in range are compacted, snapshot entire decided log
        if compacted_idx < log_decided_idx {
            Some(SnapshotType::Complete(
                self.create_snapshot(log_decided_idx)?,
            ))
        } else {
            // Entire decided log already snapshotted
            self.get_snapshot()?.map(|s| SnapshotType::Complete(s))
        }
    } else {
        let diff_entries = self.get_entries(from_idx, log_decided_idx)?;
        Some(SnapshotType::Delta(T::Snapshot::create(
            diff_entries.as_slice(),
        )))
    };
    Ok((snapshot, log_decided_idx))
}

fn load_cache(&mut self) {
    self.state_cache.promise = self
        .storage
        .get_promise()
        .expect("Failed to load cache from storage.")
        .unwrap_or_default();
    self.state_cache.decided_idx = self.storage.get_decided_idx().unwrap();
    self.state_cache.accepted_round = self
        .storage
        .get_accepted_round()
        .unwrap()
        .unwrap_or_default();
    self.state_cache.compacted_idx = self.storage.get_compacted_idx().unwrap();
    self.state_cache.stopsign = self.storage.get_stopsign().unwrap();
    self.state_cache.accepted_idx =
        self.storage.get_log_len().unwrap() + self.state_cache.compacted_idx;
    if self.state_cache.stopsign.is_some() {
        self.state_cache.accepted_idx += 1;
    }
}

/// Read all decided entries from `from_idx` in the log. Returns `None` if `from_idx` is out of bounds.
pub(crate) fn read_decided_suffix(
    &self,
    from_idx: usize,
) -> StorageResult<Option<Vec<LogEntry<T>>>> {
    let decided_idx = self.get_decided_idx();
    if from_idx < decided_idx {
        self.read(from_idx..decided_idx)
    } else {
        Ok(None)
    }
}

/// Read entries in the range `r` in the log. Returns `None` if `r` is out of bounds.
pub(crate) fn read<R>(&self, r: R) -> StorageResult<Option<Vec<LogEntry<T>>>>
where
    R: RangeBounds<usize>,
{
    let from_idx = match r.start_bound() {
        Bound::Included(i) => *i,
        Bound::Excluded(e) => *e + 1,
        Bound::Unbounded => 0,
    };
    let to_idx = match r.end_bound() {
        Bound::Included(i) => *i + 1,
        Bound::Excluded(e) => *e,
        Bound::Unbounded => self.get_accepted_idx(),
    };
    if to_idx == 0 {
        return Ok(None);
    }
    let compacted_idx = self.get_compacted_idx();
    let accepted_idx = self.get_accepted_idx();
    // use to_idx-1 when getting the entry type as to_idx is exclusive
    let to_type = match self.get_entry_type(to_idx - 1, compacted_idx, accepted_idx)? {
        Some(IndexEntry::Compacted) => {
            return Ok(Some(vec![self.create_compacted_entry(compacted_idx)?]))
        }
        Some(from_type) => from_type,
        _ => return Ok(None),
    };
    let from_type = match self.get_entry_type(from_idx, compacted_idx, accepted_idx)? {
        Some(from_type) => from_type,
        _ => return Ok(None),
    };
    match (from_type, to_type) {
        (IndexEntry::Entry, IndexEntry::Entry) => {
            Ok(Some(self.create_read_log_entries(from_idx, to_idx)?))
        }
        (IndexEntry::Entry, IndexEntry::StopSign(ss)) => {
            let mut entries = self.create_read_log_entries(from_idx, to_idx - 1)?;
            entries.push(LogEntry::StopSign(ss, self.stopsign_is_decided()));
            Ok(Some(entries))
        }
        (IndexEntry::Compacted, IndexEntry::Entry) => {
            let mut entries = Vec::with_capacity(to_idx - compacted_idx + 1);
            let compacted = self.create_compacted_entry(compacted_idx)?;
            entries.push(compacted);
            let mut e = self.create_read_log_entries(compacted_idx, to_idx)?;
            entries.append(&mut e);
            Ok(Some(entries))
        }
        (IndexEntry::Compacted, IndexEntry::StopSign(ss)) => {
            let mut entries = Vec::with_capacity(to_idx - compacted_idx + 1);
            let compacted = self.create_compacted_entry(compacted_idx)?;
            entries.push(compacted);
            let mut e = self.create_read_log_entries(compacted_idx, to_idx - 1)?;
            entries.append(&mut e);
            entries.push(LogEntry::StopSign(ss, self.stopsign_is_decided()));
            Ok(Some(entries))
        }
        (IndexEntry::StopSign(ss), IndexEntry::StopSign(_)) => {
            Ok(Some(vec![LogEntry::StopSign(
                ss,
                self.stopsign_is_decided(),
            )]))
        }
        e => {
            unimplemented!("{}", format!("Unexpected read combination: {:?}", e))
        }
    }
}

fn get_entry_type(
    &self,
    idx: usize,
    compacted_idx: usize,
    accepted_idx: usize,
) -> StorageResult<Option<IndexEntry>> {
    if idx < compacted_idx {
        Ok(Some(IndexEntry::Compacted))
    } else if idx + 1 < accepted_idx {
        Ok(Some(IndexEntry::Entry))
    } else if idx + 1 == accepted_idx {
        match self.get_stopsign() {
            Some(ss) => Ok(Some(IndexEntry::StopSign(ss))),
            _ => Ok(Some(IndexEntry::Entry)),
        }
    } else {
        Ok(None)
    }
}

fn create_read_log_entries(&self, from: usize, to: usize) -> StorageResult<Vec<LogEntry<T>>> {
    let decided_idx = self.get_decided_idx();
    let entries = self
        .get_entries(from, to)?
        .into_iter()
        .enumerate()
        .map(|(idx, e)| {
            let log_idx = idx + from;
            if log_idx < decided_idx {
                LogEntry::Decided(e)
            } else {
                LogEntry::Undecided(e)
            }
        })
        .collect();
    Ok(entries)
}

fn create_compacted_entry(&self, compacted_idx: usize) -> StorageResult<LogEntry<T>> {
    self.storage.get_snapshot().map(|snap| match snap {
        Some(s) => LogEntry::Snapshotted(SnapshottedEntry::with(compacted_idx, s)),
        None => LogEntry::Trimmed(compacted_idx),
    })
}

